-- Venue Live Guest "Wedding Opalite Aesthetic". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara opalite), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'opalite', 'Wedding Opalite Aesthetic', 'opalite', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 167, 'center 38%',
  $t${"name":"Wedding Opalite","orn":"diamond","ui":{"ivory":"#FAF7FF","white":"#FFFFFF","soft":"#EDE6F8","soft2":"#CFC3EA","accent":"#9C86CC","deep":"#4B3E6E","ink":"#3A2F5A","mute":"#8F86AD","line":"#E2DAF2","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FDFBFF","ink":"#3A2F5A","accent":"#9C86CC","gold":"#D9B97C","leaf":"#EDE6F8","hbg":"rgba(250,247,255,.94)","hline":"#D9B97C","motif":"diamond"},"hud":{"bg":"rgba(75,62,110,.92)","acc":"#F3D9FF","on":"#4B3E6E"},"scr":{"wine":"#9C86CC","veil":"250,247,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'opalite');
